import { Activity, BookOpen, ChartNoAxesCombined, Clock3, Database, FlaskConical, GitBranch, Search, Shield, Sigma } from "lucide-react";
import { endpoints, firstArray, number, pick, readApi, Json, unwrapOwner } from "./api";
import { useEffect, useState } from "react";
import { Empty, EvidenceDetails, fmtMoney, fmtPct, fmtPoints, Metric, PageHeader, Progress, Section, Status, toneOf } from "./components";
import type { ConsoleData } from "./useConsoleData";

const actions = ["buy_candidate", "add_position", "reduce_position", "sell_exit", "hold", "defensive_switch"];
const actionNames: Record<string, string> = { buy_candidate: "买入候选", add_position: "加仓", reduce_position: "减仓", sell_exit: "退出", hold: "保持", defensive_switch: "防御切换" };
function canonicalAction(value: unknown){const raw=String(value||"");return ({buy:"buy_candidate",add:"add_position",reduce:"reduce_position",sell:"sell_exit"} as Record<string,string>)[raw]||raw;}

function ownerState(owner?: Json) {
  const contract = pick(owner, [
    "questions.system_changes.champion_execution_gate",
    "champion_execution_gate",
    "execution_gate",
  ], null);
  const status = String(pick(contract, ["status"], pick(owner, ["execution_permission", "execution_mode"], "")));
  const mode = String(pick(contract, ["mode"], pick(owner, ["execution_mode"], "")));
  const reason = String(pick(contract, ["reason"], ""));
  const isolated = status === "quarantined" || mode === "research_only_sell_reduce";
  const defensiveContinuity = Boolean(pick(contract, ["defensive_continuity.enabled"], false));
  const defensiveMaximum = number(contract, ["defensive_continuity.maximum_total_weight"], 0);
  const label = isolated
    ? defensiveContinuity
      ? `研究隔离 · 防御 ETF 上限 ${fmtPct(defensiveMaximum)}`
      : "研究隔离 · 仅允许减仓和卖出"
    : status === "allowed" || mode === "normal" ? "允许正常执行" : "执行权限证据未返回";
  const statusLabel = isolated ? "研究隔离" : status === "allowed" || mode === "normal" ? "允许执行" : "证据缺失";
  return { status, mode, reason, isolated, defensiveContinuity, defensiveMaximum, label, statusLabel };
}

function acceptance(owner?: Json) {
  const raw = pick(owner, ["acceptance_progress", "acceptance", "progress"], {});
  const items = firstArray(raw, ["items", "stages"]);
  if (items.length) return items;
  return [
    { name: "候选因子评价", current: number(raw, ["factor.current", "factor_evaluations.current"]), target: number(raw, ["factor.target", "factor_evaluations.target"], 20) },
    { name: "成本候选", current: number(raw, ["cost_candidate.current", "trades.total"]), target: number(raw, ["cost_candidate.target"], 20) },
    { name: "成本自动激活", current: number(raw, ["cost_activation.current", "trades.total"]), target: number(raw, ["cost_activation.target"], 50) },
    { name: "跨日自治", current: number(raw, ["autonomy.current", "autonomous_days"]), target: number(raw, ["autonomy.target"], 20) },
  ];
}

function metricTone(value: unknown) {
  if (value === null || value === undefined || value === "" || !Number.isFinite(Number(value))) return "neutral" as const;
  return Number(value) >= 0 ? "good" as const : "danger" as const;
}

function researchStatus(row: Json) {
  const value = pick(row, ["status.status", "status.lifecycle", "lifecycle.status", "lifecycle.lifecycle", "state", "stage", "status", "lifecycle"], "已记录");
  return typeof value === "string" || typeof value === "number" ? String(value) : "已记录";
}

function scalarLabel(value: unknown, fallback = "证据缺失") {
  return typeof value === "string" || typeof value === "number" ? String(value) : fallback;
}

function ResearchDrilldown({pools,industries}:{pools:Json[];industries:Json[]}){
  const [stock,setStock]=useState(String(pick(pools[0],["ts_code","symbol"],"")));const [industry,setIndustry]=useState(String(pick(industries[0],["industry_code","code","name"],"")));const [stockEvidence,setStockEvidence]=useState<Json>({});const [industryEvidence,setIndustryEvidence]=useState<Json>({});
  useEffect(()=>{if(!stock)return;const controller=new AbortController();Promise.allSettled([["company",`/api/research/stocks/${encodeURIComponent(stock)}`],["expectations",`/api/research/expectations/${encodeURIComponent(stock)}`],["valuation",`/api/research/valuations/${encodeURIComponent(stock)}`],["eligibility",`/api/research/pools/eligibility/${encodeURIComponent(stock)}`],["financialCompleteness",`/api/data-center/financial-research-completeness/${encodeURIComponent(stock)}`]].map(async([key,path])=>[key,await readApi(path,controller.signal)] as const)).then(results=>setStockEvidence(Object.fromEntries(results.map((result,i)=>result.status==="fulfilled"?result.value:[["company","expectations","valuation","eligibility","financialCompleteness"][i],{status:"unavailable",reason:String(result.reason)}]))));return()=>controller.abort()},[stock]);
  useEffect(()=>{if(!industry)return;const controller=new AbortController();readApi(`/api/research/industries/${encodeURIComponent(industry)}`,controller.signal).then(setIndustryEvidence).catch(error=>setIndustryEvidence({status:"unavailable",reason:String(error)}));return()=>controller.abort()},[industry]);
  return <div className="two-column"><Section title="股票研究详情"><label className="detail-select"><span>研究对象</span><select value={stock} onChange={event=>setStock(event.target.value)}>{pools.map((row,i)=>{const code=String(pick(row,["ts_code","symbol"],""));return <option value={code} key={`${code}-${i}`}>{pick(row,["name"],code)} {code}</option>})}</select></label><EvidenceDetails title="公司、估值、预期、准入与财务完整度"><pre>{JSON.stringify(stockEvidence,null,2)}</pre></EvidenceDetails></Section><Section title="行业研究详情"><label className="detail-select"><span>行业</span><select value={industry} onChange={event=>setIndustry(event.target.value)}>{industries.map((row,i)=>{const code=String(pick(row,["industry_code","code","name"],""));return <option value={code} key={`${code}-${i}`}>{pick(row,["industry_name","name"],code)}</option>})}</select></label><EvidenceDetails title="行业状态与成分证据"><pre>{JSON.stringify(industryEvidence,null,2)}</pre></EvidenceDetails></Section></div>;
}

function rebalanceConclusion(rebalance: Json, isolated: boolean) {
  if (isolated) return "研究隔离，控制风险敞口";
  if (rebalance.execution_authorized) return Number(rebalance.proposal_count || 0) > 0 ? "正式调仓计划已授权" : "今日保持当前组合";
  const status = String(rebalance.status || "");
  if (status === "not_generated" || !status) return "等待正式计划";
  return "正式计划禁止执行";
}

function rebalanceReason(rebalance: Json) {
  if (rebalance.blocked_reason) return `阻断原因：${rebalance.blocked_reason}`;
  if (rebalance.execution_authorized) return `计划执行日 ${rebalance.planned_execute_date || "待确认"}`;
  return "页面只读，不会生成订单或触发交易。";
}

function ownerIncidents(owner?: Json) {
  const supervised = firstArray(owner, ["questions.incident_supervision.cases"]);
  if (supervised.length) return supervised;
  return firstArray(owner, ["questions.anomalies", "incidents", "exceptions"]);
}

export function Overview({ data }: { data: ConsoleData }) {
  const owner = unwrapOwner(data.owner); const ledger = data.ledger; const decision = data.decision; const state = ownerState(owner);
  const rebalance = pick(owner, ["questions.today_rebalance"], {});
  const profit = pick(owner, ["questions.profit"], {});
  const changes = pick(owner, ["questions.system_changes"], {});
  const equity = pick(ledger, ["total_equity"], pick(owner, ["account.total_equity", "total_equity"]));
  const actionsList = firstArray(rebalance, ["actions"]);
  const incidents = ownerIncidents(owner);
  const dailyTone = metricTone(pick(profit, ["daily_return_pct"]));
  const excessTone = metricTone(pick(profit, ["excess_return"]));
  return <>
    <PageHeader eyebrow="OWNER CONSOLE" title="投资系统总览" summary="今天是否安全运行、账户表现如何，以及哪些事情值得你关注。" />
    <div className="state-ribbon"><div><span>系统状态</span><Status tone={state.isolated ? "watch" : pick(owner,["healthy"],false) ? "good" : "watch"}>{pick(owner,["healthy"],false) ? "正常" : data.owner?.available === false ? "等待首个自治周期" : "保护运行"}</Status></div><div><span>今日执行权限</span><strong>{state.label}</strong></div><div><span>最近完整周期</span><strong>{pick(data.owner, ["finished_at"], pick(owner, ["generated_at"], "--"))}</strong></div></div>
    {state.isolated && <div className="isolation-banner"><Shield size={21}/><div><strong>Champion 正式 OOS 失效，当前处于研究隔离</strong><p>{state.defensiveContinuity ? `禁止个股新开仓和加仓；允许最多 ${fmtPct(state.defensiveMaximum)} 的登记防御 ETF，以及减仓、卖出、账本审计和候选研究。` : "禁止新开仓、加仓和防御资产补仓；只允许减仓、卖出、账本审计和候选研究。"}</p></div></div>}
    <Section title="今日调仓结论" detail="正式计划优先，页面读取不会生成订单。"><div className="decision-callout"><div><span>结论</span><strong>{rebalanceConclusion(rebalance, state.isolated)}</strong><p>{rebalanceReason(rebalance)}</p></div><div className="action-count">{pick(rebalance,["proposal_count"],actionsList.length)}<small>项动作</small></div></div></Section>
    <div className="two-column"><Section title="账户净值" detail="模拟账户独立账本"><div className="metric-grid"><Metric label="总权益" value={fmtMoney(equity)} /><Metric label="可用现金" value={fmtMoney(pick(ledger, ["cash_balance"]))} /><Metric label="持仓市值" value={fmtMoney(pick(ledger, ["position_market_value"]))} /><Metric label="累计盈亏" value={fmtMoney(pick(ledger, ["equity_delta"]))} tone={number(ledger, ["equity_delta"]) >= 0 ? "good" : "danger"}/></div></Section>
    <Section title="相对沪深300" detail={`百分点口径 · ${pick(profit,["benchmark_period_start"],"--")} 至 ${pick(profit,["benchmark_period_end"],"--")}`}><div className="metric-grid"><Metric label="账户日收益" value={fmtPoints(pick(profit,["daily_return_pct"]))} tone={dailyTone}/><Metric label="账户月收益" value={fmtPoints(pick(profit,["monthly_return_pct"]))} tone={metricTone(pick(profit,["monthly_return_pct"]))}/><Metric label="沪深300同期" value={fmtPoints(pick(profit,["benchmark_return"]))}/><Metric label="累计超额" value={fmtPoints(pick(profit,["excess_return"]))} tone={excessTone}/></div></Section></div>
    <Section title="距离下一次验收还差多少" detail="进度取各硬门的最短板，不用平均值掩盖缺口。"><div className="progress-grid">{acceptance(owner).map((item, index) => <Progress key={index} label={String(item.name || item.label || "验收项")} current={Number(item.current ?? item.value ?? 0)} target={Number(item.target ?? 1)} suffix={String(item.unit || "")} />)}</div></Section>
    <Section title="异常与系统自行处理事项" detail="只有需要所有者授权的事项会提升为强通知。">{incidents.length ? <div className="incident-list">{incidents.slice(0, 6).map((item, i) => <div key={i}><Status>{pick(item, ["disposition", "status"], "观察")}</Status><div><strong>{pick(item, ["title", "summary", "name"], "运行事项")}</strong><p>{pick(item, ["next_review", "reason", "detail"], "等待下一周期复核")}</p></div></div>)}</div> : <Empty title="没有需要所有者处理的事项" detail="等待未来样本和冷却期不计为故障。" />}<a className="text-link" href="/operations">查看系统运行证据 →</a></Section>
  </>;
}

export function TodayDecision({ data }: { data: ConsoleData }) {
  const decision = data.decision; const owner = unwrapOwner(data.owner); const state = ownerState(owner);
  const rebalance = pick(owner, ["questions.today_rebalance"], {});
  const items = firstArray(rebalance, ["actions"]);
  return <><PageHeader eyebrow="TODAY'S PLAN" title="今日决策" summary="围绕正式调仓计划查看动作、权重、执行状态与冻结证据。" />
    <div className={`decision-status ${state.isolated ? "danger-zone" : ""}`}><div><span>当前结论</span><h2>{rebalanceConclusion(rebalance,state.isolated)}</h2><p>{rebalanceReason(rebalance)}</p></div><Status tone={state.isolated ? "danger" : rebalance.execution_authorized ? "good" : "watch"}>{state.isolated ? "研究隔离" : rebalance.execution_authorized ? "允许执行" : "禁止执行"}</Status></div>
    <Section title="动作清单" detail="按 StrategyController 统一动作合同分组。">{items.length ? <div className="action-groups">{actions.map((action) => { const rows = items.filter((x) => canonicalAction(x.action || x.action_type) === action); return <div key={action}><header><strong>{actionNames[action]}</strong><span>{rows.length}</span></header>{rows.length ? rows.map((row, i) => <article key={i}><div><b>{pick(row, ["name", "symbol_name", "ts_code", "symbol"], "未命名资产")}</b><small>{pick(row, ["symbol", "ts_code"], "")}</small></div><p>{pick(row, ["reason", "action_reason", "thesis"], "原因记录待返回")}</p><strong>{fmtPct(pick(row, ["target_weight", "weight"]), false)}</strong></article>) : <small className="muted">无动作</small>}</div>; })}</div> : <Empty title="暂无正式动作" detail="可能是保持、数据门阻断或计划尚未生成。" />}</Section>
    <div className="two-column"><Section title="权重与金额" detail="当前摘要只返回正式动作；完整权重见冻结证据。"><DecisionTable items={items} /></Section><Section title="执行状态" detail="计划与成交严格分离。"><dl className="fact-list"><div><dt>计划状态</dt><dd><Status>{pick(rebalance,["status"],"未生成")}</Status></dd></div><div><dt>计划日期</dt><dd>{pick(rebalance,["plan_date"],"--")}</dd></div><div><dt>计划执行日</dt><dd>{pick(rebalance,["planned_execute_date"],"--")}</dd></div><div><dt>执行授权</dt><dd>{rebalance.execution_authorized ? "是" : "否"}</dd></div><div><dt>阻断原因</dt><dd>{pick(rebalance,["blocked_reason"],"无")}</dd></div></dl></Section></div>
    <Section title="决策原因" detail="收益来源、风险预算和退出合同缺一不可。"><div className="reason-grid">{["收益来源假设", "触发模型", "风险预算", "持有周期", "退出条件", "禁止条件"].map((label, i) => { const field=["expected_return_source","trigger_models","risk_budget","holding_period","exit_conditions","prohibitions"][i]; return <div key={label}><span>{label}</span><p>{String(pick(items[0]||decision, [field], "未返回"))}</p></div>})}</div><EvidenceDetails title="完整决策证据"><pre>{JSON.stringify({decision,rebalance}, null, 2)}</pre></EvidenceDetails></Section>
  </>;
}

function DecisionTable({ items }: { items: Json[] }) { return items.length ? <div className="table-wrap"><table><thead><tr><th>资产</th><th>动作</th><th>当前</th><th>目标</th><th>预计金额</th></tr></thead><tbody>{items.map((row, i) => <tr key={i}><td><strong>{pick(row,["name","symbol_name","symbol","ts_code"],"--")}</strong></td><td>{actionNames[canonicalAction(row.action || row.action_type)] || row.action || "--"}</td><td>{fmtPct(pick(row,["current_weight"]),false)}</td><td>{fmtPct(pick(row,["target_weight","weight"]),false)}</td><td>{fmtMoney(pick(row,["estimated_amount","target_amount"]))}</td></tr>)}</tbody></table></div> : <Empty />; }

export function Portfolio({ data }: { data: ConsoleData }) {
  const ledger = data.ledger; const positions = firstArray(data.positions, ["positions"]);
  const competition = pick(data.research, ["portfolio_optimization.optimizer.method_competition","portfolio_optimization.method_competition"], {});
  const methods = firstArray(competition, ["evaluations"]);
  return <><PageHeader eyebrow="ACCOUNT & PORTFOLIO" title="账户与组合" summary="钱在哪里、为什么这样配置，以及风险和账本是否可信。" />
    <div className="metric-grid headline-metrics"><Metric label="账户权益" value={fmtMoney(pick(ledger,["total_equity"]))}/><Metric label="现金" value={fmtMoney(pick(ledger,["cash_balance"]))}/><Metric label="持仓市值" value={fmtMoney(pick(ledger,["position_market_value"]))}/><Metric label="持仓数量" value={pick(ledger,["position_count"],"--")} note={`估值日 ${pick(ledger,["valuation_date"],"--")}`}/></div>
    <Section title="净值与基准" detail="账户曲线与沪深300共同首日归一化。"><Curve data={data.portfolio || data.performance} /></Section>
    <div className="two-column wide-left"><Section title="当前持仓" detail={`价格数据时间 ${pick(data.positions,["data_source_time"],"--")}`}>{positions.length ? <div className="table-wrap"><table><thead><tr><th>持仓</th><th>数量</th><th>当前市值</th><th>盈亏</th><th>策略下一步</th></tr></thead><tbody>{positions.map((row,i)=><tr key={i}><td><strong>{pick(row,["name","symbol"],"--")}</strong><small>{pick(row,["symbol"],"")}</small></td><td>{pick(row,["quantity"],"--")}</td><td>{fmtMoney(pick(row,["current_value"]))}</td><td className={metricTone(pick(row,["profit_loss"]))==="good"?"positive":metricTone(pick(row,["profit_loss"]))==="danger"?"negative":""}>{fmtMoney(pick(row,["profit_loss"]))}</td><td>{pick(row,["strategy_next"],"--")}</td></tr>)}</tbody></table></div>:<Empty />}</Section><Section title="风险概览" detail="风险贡献和交易容量为只读证据。"><dl className="fact-list"><div><dt>经验 CVaR</dt><dd>{fmtPct(pick(data.risk,["tail_risk.cvar","cvar","portfolio_cvar"]),false)}</dd></div><div><dt>风险状态</dt><dd><Status>{pick(data.risk,["status"],"证据缺失")}</Status></dd></div><div><dt>约束违规</dt><dd>{firstArray(data.risk,["breaches"]).length}</dd></div><div><dt>压力场景</dt><dd>{firstArray(data.risk,["stress_tests"]).length}</dd></div><div><dt>账本一致性</dt><dd><Status>{pick(unwrapOwner(data.owner),["questions.system_changes.ledger_status"],"证据缺失")}</Status></dd></div></dl></Section></div>
    <Section title="组合方案竞赛" detail="优化器参数不作为日常编辑项，只展示选择证据。">{methods.length?<div className="table-wrap"><table><thead><tr><th>方案</th><th>目标值</th><th>CVaR</th><th>换手</th><th>结论</th></tr></thead><tbody>{methods.map((row,i)=><tr key={i}><td><strong>{pick(row,["method"],"--")}</strong></td><td>{pick(row,["objective"],"--")}</td><td>{fmtPct(pick(row,["cvar_20d","cvar"]),false)}</td><td>{fmtPct(pick(row,["turnover"]),false)}</td><td><Status>{String(pick(row,["method"],""))===String(pick(competition,["selected_method"],""))?"选择":"拒绝"}</Status></td></tr>)}</tbody></table></div>:<Empty title="暂无组合竞赛证据" detail="最近周期未返回方法对比明细。" />}</Section>
  </>;
}

function Curve({ data }: { data?: Json }) {
  const series=firstArray(data,["series","curve","items"]).slice(-60);if(!series.length)return <Empty title="暂无连续净值曲线" detail="更长历史将随模拟成交自然积累。"/>;
  const rows=series.map(row=>({date:String(pick(row,["date","trade_date"],"")),portfolio:Number(pick(row,["close","strategy_equity","equity","value"],NaN)),benchmark:Number(pick(row,["benchmark_close","benchmark","benchmark_value"],NaN))})).filter(row=>Number.isFinite(row.portfolio));if(!rows.length)return <Empty title="净值字段尚未返回" detail="曲线接口已有记录，但没有可绘制的账户净值。"/>;
  const all=rows.flatMap(row=>[row.portfolio,row.benchmark]).filter(Number.isFinite);const rawMin=Math.min(...all),rawMax=Math.max(...all);const padding=Math.max((rawMax-rawMin)*.15,.2);const min=rawMin-padding,max=rawMax+padding;const point=(value:number,index:number)=>`${5+index/Math.max(rows.length-1,1)*90},${88-(value-min)/(max-min)*72}`;const portfolioPoints=rows.map((row,index)=>point(row.portfolio,index)).join(" ");const benchmarkRows=rows.map((row,index)=>({value:row.benchmark,index})).filter(row=>Number.isFinite(row.value));const benchmarkPoints=benchmarkRows.map(row=>point(row.value,row.index)).join(" ");const portfolioReturn=rows.length>1?rows[rows.length-1].portfolio/rows[0].portfolio-1:0;const firstBenchmark=benchmarkRows[0]?.value,lastBenchmark=benchmarkRows[benchmarkRows.length-1]?.value;const benchmarkReturn=firstBenchmark&&lastBenchmark?lastBenchmark/firstBenchmark-1:null;
  return <div className="curve"><div className="curve-legend"><span><i className="portfolio-line"/>账户净值</span><span><i className="benchmark-line"/>沪深300</span></div><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="账户净值与沪深300曲线"><line x1="5" y1="88" x2="95" y2="88"/><polyline className="portfolio-line" points={portfolioPoints}/>{benchmarkPoints&&<polyline className="benchmark-line" points={benchmarkPoints}/>}</svg><div><span>{rows[0].date}</span><strong>账户 {fmtPct(portfolioReturn)} · 基准 {benchmarkReturn===null?"--":fmtPct(benchmarkReturn)}</strong><span>{rows[rows.length-1].date}</span></div></div>;
}

export function Evolution({ data }: { data: ConsoleData }) {
  const [view,setView]=useState<"pipeline"|"factors"|"strategies">("pipeline");
  const [liveResearch,setLiveResearch]=useState<Json|undefined>(data.factorResearch);
  const [liveTasks,setLiveTasks]=useState<Json|undefined>(data.evolutionTasks);
  const [liveOwner,setLiveOwner]=useState<Json|undefined>(data.owner);
  const [liveUpdatedAt,setLiveUpdatedAt]=useState("");
  const [liveError,setLiveError]=useState("");
  const [populationStage,setPopulationStage]=useState<"all"|"quick_screen"|"confirmation">("all");
  const [populationSort,setPopulationSort]=useState<"fitness"|"drawdown"|"delta">("fitness");
  useEffect(()=>{
    let active=true;let inFlight=false;const controller=new AbortController();
    const poll=async()=>{if(inFlight)return;inFlight=true;const results=await Promise.allSettled([
      readApi("/api/factors/research/status",controller.signal),
      readApi("/api/model-strategy/evolution/tasks?limit=30",controller.signal),
      readApi("/api/model-strategy/evolution/owner-summary",controller.signal),
    ]);inFlight=false;if(!active)return;let successful=false;
      if(results[0].status==="fulfilled"){setLiveResearch(results[0].value);successful=true}
      if(results[1].status==="fulfilled"){setLiveTasks(results[1].value);successful=true}
      if(results[2].status==="fulfilled"){setLiveOwner(results[2].value);successful=true}
      setLiveError(results.every(result=>result.status==="rejected")?"实时状态暂时不可用，正在重试":"");
      if(successful)setLiveUpdatedAt(new Date().toLocaleTimeString("zh-CN",{hour12:false}));
    };
    void poll();const timer=window.setInterval(()=>void poll(),5000);
    return()=>{active=false;controller.abort();window.clearInterval(timer)};
  },[]);
  useEffect(()=>{if(data.factorResearch)setLiveResearch(data.factorResearch)},[data.factorResearch]);
  useEffect(()=>{if(data.evolutionTasks)setLiveTasks(data.evolutionTasks)},[data.evolutionTasks]);
  useEffect(()=>{if(data.owner)setLiveOwner(data.owner)},[data.owner]);
  const lab=data.strategy; const champion=pick(lab,["champion","production_strategy"],{}); const challengers=firstArray(lab,["challengers","candidates","items"]); const baselines=firstArray(lab,["baselines"]); const state=ownerState(unwrapOwner(liveOwner||data.owner));
  const factorRows=rowsFrom(data.factors,["definitions","factors","registry","items"]);
  const factorLabels=Object.fromEntries(factorRows.map(row=>[
    String(pick(row,["factor_key"],"")),
    String(pick(row,["name_cn","name","factor_key"],"")),
  ]).filter(([key])=>key));
  const factorResearch=liveResearch||data.factorResearch||{};const population=firstArray(factorResearch,["population"]);const best=pick(factorResearch,["best_experiment"],{}) as Json;
  const lineageRows=rowsFrom(data.factorLineage,["combinations","lineage","items"]);
  const evolutionTasks=rowsFrom(liveTasks||data.evolutionTasks,["items","tasks"]);
  const researchTask=evolutionTasks.find(row=>String(pick(row,["task_type"],""))==="factor_research_cycle"&&["queued","running","retry_wait"].includes(String(pick(row,["status"],""))));
  const completedExperiments=Number(pick(factorResearch,["experiment_count"],0));
  const snapshot=pick(factorResearch,["snapshot"],{}) as Json;
  const factorUniverseCount=factorRows.length||Number(pick(snapshot,["factor_count"],0))||"--";
  const activeCount=data.factors?Number(pick(data.factors,["active_count"],factorRows.filter(row=>["active","production"].includes(String(row.status))).length)):"--";
  const candidateCount=data.factors?Number(pick(data.factors,["candidate_count"],factorRows.filter(row=>String(row.status)==="candidate").length)):"--";
  const researchRunning=Boolean(researchTask)||String(pick(factorResearch,["status"],""))==="running";
  const rawTaskProgress=Number(pick(researchTask,["progress"],0));const taskProgress=Math.round((rawTaskProgress<=1?rawTaskProgress*100:rawTaskProgress)*10)/10;
  const quickDone=Number(pick(factorResearch,["quick_screen_completed"],0));const quickTarget=Number(pick(factorResearch,["quick_screen_target"],12));
  const confirmationDone=Number(pick(factorResearch,["confirmation_completed"],0));const confirmationTarget=Number(pick(factorResearch,["confirmation_target"],3));
  const visiblePopulation=population.filter(row=>populationStage==="all"||String(row.research_stage)===populationStage).slice().sort((left,right)=>{
    if(populationSort==="drawdown")return Number(pick(right,["metrics.worst_drawdown"],-1))-Number(pick(left,["metrics.worst_drawdown"],-1));
    if(populationSort==="delta")return Number(pick(right,["metrics.fitness_delta_vs_parent"],-999))-Number(pick(left,["metrics.fitness_delta_vs_parent"],-999));
    return Number(right.fitness||0)-Number(left.fitness||0);
  });
  const gates=["候选来源","快速诊断","正式 OOS","统计门 / DSR","密封保留集","未来 Shadow","冷却与晋升"];
  return <><PageHeader eyebrow="RESEARCH & EVOLUTION" title="研究与进化" summary="从因子发现、组合搜索和策略蒸馏，到 Challenger 正式验证与 Champion 晋升。" />
    <div className="research-tabs evolution-tabs" role="tablist">{[
      ["pipeline","全链路",GitBranch],["factors","因子研究",Sigma],["strategies","策略晋升",ChartNoAxesCombined],
    ].map(([key,label,Icon]:any)=><button key={key} className={view===key?"active":""} onClick={()=>setView(key)}><Icon size={16}/><span>{label}</span></button>)}</div>
    <div className={`live-research-bar ${researchRunning?"is-running":""}`}><div className="live-research-icon"><Activity size={18}/></div><div><span>连续因子研究</span><strong>{researchTask?`任务 #${pick(researchTask,["id"],"--")} · ${pick(researchTask,["message","phase"],"执行中")}`:researchRunning?"后台研究批次执行中":"当前没有运行中的组合回测"}</strong><small>{liveError||`每 5 秒自动刷新${liveUpdatedAt?` · 最近更新 ${liveUpdatedAt}`:""}`}</small></div><div className="live-progress"><b>{researchTask?`${taskProgress}%`:researchRunning?"运行中":"空闲"}</b><span><i style={{width:`${researchTask?taskProgress:researchRunning?8:0}%`}}/></span></div></div>
    {view==="pipeline"&&<><div className="metric-grid headline-metrics"><Metric label="因子宇宙" value={factorUniverseCount} note={`${activeCount} 生产 · ${candidateCount} 候选`}/><Metric label="组合实验" value={completedExperiments} note={`数据截止 ${pick(snapshot,["data_as_of"],"--")}`}/><Metric label="存活组合" value={population.length} note="前 3 名作为精英父代"/><Metric label="连续研究" value={<Status>{researchTask?pick(researchTask,["status"],"running"):pick(factorResearch,["status"],"not_started")}</Status>} note={researchTask?pick(researchTask,["message","phase"],"后台执行中"):researchRunning?"后台连续研究中":"等待下一研究批次"}/></div>
    <Section title="因子到 Champion 的证据链" detail="研究筛选和生产晋升使用不同证据，任何快速回测都不能直接改写生产。"><div className="evolution-pipeline">{[
      ["01","发现因子",`${factorUniverseCount} 个已注册`,"历史字段与受约束公式"],
      ["02","组合搜索",`${completedExperiments} 次实验`,"冻结截面、成本后回测"],
      ["03","选择父代",`${population.length} 个存活`,"保留精英并定向变异"],
      ["04","蒸馏策略",`${lineageRows.length} 条谱系`,"形成 research-only 候选"],
      ["05","正式验证",`${challengers.length} 个 Challenger`,"OOS、DSR、密封、Shadow"],
      ["06","生产晋升","唯一 Champion","冷却、回退和执行隔离"],
    ].map(([step,title,value,note],index)=><article key={step}><span>{step}</span><div><h3>{title}</h3><strong>{value}</strong><p>{note}</p></div>{index<5&&<i/>}</article>)}</div></Section>
    <div className="two-column"><Section title="当前最优研究组合" detail="只用于决定下一轮搜索方向，不是生产收益证明。">{best&&Object.keys(best).length?<><div className="research-best"><div><span>FITNESS</span><strong>{Number(pick(best,["fitness"],0)).toFixed(4)}</strong></div><dl className="fact-list"><div><dt>代次</dt><dd>{pick(best,["generation"],"--")}</dd></div><div><dt>状态</dt><dd><Status>{pick(best,["status"],"--")}</Status></dd></div><div><dt>变异</dt><dd>{pick(best,["mutation_type"],"--")}</dd></div><div><dt>正式 OOS 证据</dt><dd>否</dd></div></dl></div><FactorWeights weights={pick(best,["factor_weights"],{})} labels={factorLabels}/></>:<Empty title="等待首个组合完成" detail="后台会自动生成、回测并保留组合。"/>}</Section><Section title="当前晋升结论" detail="清楚区分“研究表现较好”和“有资格接管生产”。"><div className="promotion-verdict"><Status tone={state.isolated?"danger":"good"}>{state.isolated?"Champion 失效隔离":"Champion 正常执行"}</Status><h3>{challengers.length?`${challengers.length} 个 Challenger 正在验证`:"尚无可晋升 Challenger"}</h3><p>{challengers.length?"候选仍须逐项通过正式统计门；研究组合不会直接进入账户。":"系统将继续从因子组合中蒸馏候选，同时保留唯一 Champion。"} </p></div></Section></div></>}
    {view==="factors"&&<><div className="metric-grid headline-metrics"><Metric label="注册因子" value={factorUniverseCount}/><Metric label="生产因子" value={activeCount}/><Metric label="候选因子" value={candidateCount}/><Metric label="研究阶段" value={<Status>{researchStageLabel(pick(factorResearch,["current_stage"],pick(factorResearch,["status"],"not_started")))}</Status>} note={`快筛 ${quickDone}/${quickTarget} · 复筛 ${confirmationDone}/${confirmationTarget}`}/></div>
    <div className="research-stage-map"><div className={quickDone<quickTarget?"active":"done"}><span>1</span><section><strong>快速筛选</strong><p>2×15 日 · {quickDone}/{quickTarget} 个组合</p><div><i style={{width:`${Math.min(100,quickDone/Math.max(1,quickTarget)*100)}%`}}/></div></section></div><b>→</b><div className={quickDone>=quickTarget&&confirmationDone<confirmationTarget?"active":confirmationDone>=confirmationTarget?"done":""}><span>2</span><section><strong>多窗口复筛</strong><p>3×30 日 · {confirmationDone}/{confirmationTarget} 个精英</p><div><i style={{width:`${Math.min(100,confirmationDone/Math.max(1,confirmationTarget)*100)}%`}}/></div></section></div><b>→</b><div className={confirmationDone>=confirmationTarget?"active":""}><span>3</span><section><strong>策略蒸馏</strong><p>进入未来证据与正式 OOS</p></section></div></div>
    <Section title="连续组合研究" detail="先做短窗口快速筛选，再让精英组合进入更长多窗口复筛；所有结果仍是 research-only。"><div className="population-toolbar"><div>{[["all","全部"],["quick_screen","快速筛选"],["confirmation","多窗口复筛"]].map(([key,label])=><button key={key} className={populationStage===key?"active":""} onClick={()=>setPopulationStage(key as typeof populationStage)}>{label}</button>)}</div><label><span>排序</span><select value={populationSort} onChange={event=>setPopulationSort(event.target.value as typeof populationSort)}><option value="fitness">研究适应度</option><option value="drawdown">最大回撤</option><option value="delta">相对父代改善</option></select></label></div>{visiblePopulation.length?<div className="population-grid">{visiblePopulation.map((row,i)=><article key={String(row.experiment_id||i)}><header><span>#{pick(row,["rank"],i+1)}</span><Status>{researchRoleLabel(pick(row,["role"],"survivor"))}</Status></header><strong>{Number(pick(row,["fitness"],0)).toFixed(4)}</strong><small>{researchStageLabel(pick(row,["research_stage"],"quick_screen"))} · 第 {pick(row,["generation"],"--")} 代</small><FactorWeights weights={pick(row,["factor_weights"],{})} labels={factorLabels}/><ResearchMetrics row={row}/><footer><span>{mutationLabel(pick(row,["mutation_type"],"diverse_seed"))}</span><code>{row.parent_experiment_id?`父代 ${String(row.parent_experiment_id).slice(-8)}`:"初始种子"}</code></footer></article>)}</div>:<Empty title="当前筛选下没有组合" detail="切换到其他研究阶段，或等待后台完成新的组合实验。"/>}</Section><Section title="因子注册表" detail="生产、候选和交易约束分别治理；交易约束不参与 Alpha IC 晋升。"><CompactTable rows={factorRows} columns={[["因子","name_cn","factor_key","name"],["键","factor_key"],["状态","status","stage"],["版本","version","registry_version"],["分类","category"]]}/></Section><EvidenceDetails title="查看因子研究原始合同"><pre>{JSON.stringify({research:factorResearch,lineage:data.factorLineage,registry:data.factors,status:data.factorStatus},null,2)}</pre></EvidenceDetails></>}
    {view==="strategies"&&<>
    <Section title="唯一 Champion" detail="正式生产绑定与执行隔离必须同时展示。"><div className="champion"><div><span>CHAMPION</span><h2>{pick(champion,["name","strategy_name"],"ALIS Production Strategy")}</h2><p>版本 {pick(champion,["version","version_id"],"--")} · {pick(champion,["controller_version","strategy_controller_version"],"Controller --")}</p></div><div><Status tone={state.isolated?"danger":"good"}>{state.isolated?"研究隔离":"生产登记"}</Status><small>{state.isolated?(state.defensiveContinuity?`防御 ETF ≤ ${fmtPct(state.defensiveMaximum)}`:"仅减仓 / 卖出"):"正常执行合同"}</small></div></div></Section>
    <Section title="晋升漏斗" detail="每个候选只显示当前唯一阻塞原因。"><div className="funnel">{gates.map((gate,i)=><div key={gate}><span>{i+1}</span><strong>{gate}</strong>{i<gates.length-1&&<i/>}</div>)}</div></Section>
    <Section title="Challenger" detail="公开研究门通过前，不消费密封历史保留集。">{challengers.length?<div className="challengers">{challengers.map((row,i)=><article key={i}><header><div><Status>{pick(row,["status","stage"],"候选")}</Status><h3>{pick(row,["name","strategy_name"],`Challenger ${i+1}`)}</h3></div><strong>{fmtPct(pick(row,["formal_oos.aggregate_excess_return","excess_return"]))}</strong></header><div className="candidate-stats"><span>OOS <b>{pick(row,["formal_oos.status"],"pending")}</b></span><span>窗口胜出 <b>{pick(row,["formal_oos.outperform_windows"],0)}/{pick(row,["formal_oos.valid_windows"],0)}</b></span><span>Shadow <b>{pick(row,["shadow.session_count"],0)}/{pick(row,["shadow.minimum_sessions"],20)}日</b></span></div><div className="blocker"><Clock3 size={16}/><span><b>当前阻塞：</b>{(firstArray(row,["blocking_reasons"]).join("、")||pick(row,["next_gate"],"等待下一阶段证据"))}</span></div></article>)}</div>:<Empty title="暂无 Challenger 明细" detail="候选证据可能尚未物化或接口未返回。" />}</Section>
    <div className="two-column"><Section title="正式 OOS 基线" detail="成本后、同窗口、同版本合同。"><dl className="leaderboard">{baselines.map((row,i)=><div key={i}><dt>{pick(row,["name","baseline_key"],"基线")}</dt><dd>{fmtPct(pick(row,["formal_oos.aggregate_cost_after_return"]))}</dd></div>)}</dl></Section><Section title="密封集与 Shadow" detail="密封集绝不展示详细收益。"><dl className="fact-list"><div><dt>数据就绪</dt><dd><Status>{pick(data.sealed,["status"],"证据缺失")}</Status></dd></div><div><dt>完整度</dt><dd>{pick(data.sealed,["eligible_sessions"],"--")}/{pick(data.sealed,["required_sessions"],126)} 日</dd></div><div><dt>生产候选</dt><dd>{pick(lab,["summary.production_eligible_count"],0)}</dd></div><div><dt>Shadow 门</dt><dd>20～60 个未来交易日</dd></div></dl></Section></div>
    <EvidenceDetails title="查看策略版本与统计证据"><pre>{JSON.stringify(lab||{},null,2)}</pre></EvidenceDetails>
    </>}
  </>;
}

function FactorWeights({weights,labels={}}:{weights:unknown,labels?:Record<string,string>}){const rows=weights&&typeof weights==="object"&&!Array.isArray(weights)?Object.entries(weights as Json).sort((a,b)=>Math.abs(Number(b[1]))-Math.abs(Number(a[1]))):[];return rows.length?<div className="factor-weights">{rows.map(([key,value])=><div key={key}><span><b>{labels[key]||factorFallbackLabel(key)}</b><small>{key}</small></span><strong>{Number(value)>0?"+":""}{Number(value).toFixed(3)}</strong></div>)}</div>:<Empty title="暂无因子权重" detail="组合尚未返回权重合同。"/>}
function factorFallbackLabel(key:string){const words:Record<string,string>={earnings:"盈利",yield:"收益率",book:"账面",price:"价格",value:"价值",lowvol:"低波动",interaction:"交互",short:"短期",reversal:"反转",medium:"中期",momentum:"动量",intraday:"日内",position:"位置",total:"总",mv:"市值",volume:"成交量",turnover:"换手",volatility:"波动率",ratio:"比率",beta:"贝塔",size:"规模",range:"振幅",contraction:"收缩",open:"开盘",close:"收盘",corr:"相关"};return key.split("_").filter(part=>part!=="alpha"&&part!=="dsl").map(part=>words[part]||part).join("")||key}
function ResearchMetrics({row}:{row:Json}){const metrics=pick(row,["metrics"],{}) as Json;const delta=pick(metrics,["fitness_delta_vs_parent"],null);return <dl className="research-row-metrics"><div><dt>平均超额</dt><dd>{fmtPct(pick(metrics,["mean_excess_return"]))}</dd></div><div><dt>最大回撤</dt><dd>{fmtPct(pick(metrics,["worst_drawdown"]))}</dd></div><div><dt>稳定性</dt><dd>{Number(pick(metrics,["excess_instability"],0)).toFixed(4)}</dd></div><div><dt>相对父代</dt><dd className={delta===null?"":Number(delta)>=0?"positive":"negative"}>{delta===null?"首代":`${Number(delta)>=0?"+":""}${Number(delta).toFixed(4)}`}</dd></div></dl>}
function researchStageLabel(value:unknown){return ({quick_screen:"快速筛选",confirmation:"多窗口复筛",running:"研究运行中",budget_exhausted:"本批次完成",not_started:"尚未开始"} as Record<string,string>)[String(value)]||String(value||"未知")}
function researchRoleLabel(value:unknown){return ({confirmed_elite:"复筛精英",fitness_elite:"适应度精英",drawdown_elite:"低回撤精英",stability_elite:"稳定性精英",diversity_survivor:"多样性保留",fitness_survivor:"适应度保留",elite:"精英",survivor:"保留"} as Record<string,string>)[String(value)]||String(value||"保留")}
function mutationLabel(value:unknown){return ({diverse_seed:"初始多样化种子",drop_weakest:"移除最弱因子",add_novel_factor:"加入新因子",tilt_existing_factor:"增强现有因子",replace_factor:"替换因子",confirmation_replay:"进入多窗口复筛"} as Record<string,string>)[String(value)]||String(value||"未知变异")}

function ScoreBar({value}:{value:unknown}){const score=Math.max(0,Math.min(100,Number(value)||0));return <div className="score-cell"><strong>{score.toFixed(1)}</strong><span><i style={{width:`${score}%`}}/></span></div>}
function industryConclusion(row:Json){if(row.eligible===true)return "已准入";if(Array.isArray(row.blockers)&&row.blockers.length)return "未准入";return scalarLabel(pick(row,["status","state.status"],"证据不足"),"证据不足")}

export function Research({ data }: { data: ConsoleData }) {
  const [view,setView]=useState<"industries"|"themes"|"pools"|"events">("industries");const theses=firstArray(data.theses,["items","theses"]);const validIndustry=(row:Json)=>{const label=String(pick(row,["industry","industry_name","industry_code"],"")).trim().toLowerCase();return Boolean(label)&&label!=="nan"};const industries=firstArray(data.industries,["items","industries"]).filter(validIndustry);const themes=firstArray(data.themes,["items","themes"]);const events=firstArray(data.events,["items","events"]);const pools=firstArray(data.pools,["items","members","pools"]);const allocation=firstArray(data.industryAllocation,["items"]).filter(validIndustry);const industryRows=(allocation.length?allocation:industries).slice().sort((a,b)=>Number(pick(b,["combined_score","state.score"],0))-Number(pick(a,["combined_score","state.score"],0)));const themeRows=themes.slice().sort((a,b)=>Number(b.score||0)-Number(a.score||0));const poolRows:Json[]=pools.map(row=>{const match=String(row.reason||"").match(/research_score=([\d.]+)/);return {...row,research_score:Number(pick(row,["research_state.score","score"],match?.[1]||0))}}).sort((a,b)=>b.research_score-a.research_score);const eventRows=events.slice().sort((a,b)=>Number(pick(b,["impact.decayed_score","impact.score","score"],0))-Number(pick(a,["impact.decayed_score","impact.score","score"],0)));const marketState=pick(data.modelMarketLive,["market_state.label","market_state.state","state.label","state.state"],"证据缺失");
  return <><PageHeader eyebrow="RESEARCH" title="研究中心" summary="比较行业、板块、主题和股票研究评分，并下钻到点时证据与失效条件。"/><div className="metric-grid headline-metrics"><Metric label="市场状态" value={<Status>{marketState}</Status>} note={pick(data.modelMarketLive,["trade_date","as_of_date"],"--")}/><Metric label="可评价行业" value={industries.filter(row=>pick(row,["state.status"],"")==="ready").length} note={`共 ${industries.length} 个行业`}/><Metric label="可晋升主题" value={themes.filter(row=>Boolean(row.promotable)).length} note={`共 ${themes.length} 个主题`}/><Metric label="研究股票池" value={pools.length} note={`${theses.length} 条投资逻辑`}/></div><div className="research-tabs" role="tablist">{[["industries","行业与板块",Activity],["themes","主题与叙事",FlaskConical],["pools","股票池",BookOpen],["events","事件与反证",Clock3]].map(([key,label,Icon]:any)=><button key={key} className={view===key?"active":""} onClick={()=>setView(key)}><Icon size={16}/><span>{label}</span></button>)}</div>
    {view==="industries"&&<Section title="行业与板块评分" detail="综合分 = 叙事 60% + 行业质量 20% + 候选选择分 20%；预算只分配给通过准入门的行业。"><div className="table-wrap"><table><thead><tr><th>排名</th><th>行业 / 板块</th><th>综合分</th><th>景气分</th><th>叙事分</th><th>覆盖</th><th>生命周期</th><th>预算权重</th><th>结论</th></tr></thead><tbody>{industryRows.map((row,i)=><tr key={String(pick(row,["industry","industry_code","industry_name"],i))}><td>{i+1}</td><td><strong>{pick(row,["industry","industry_name"],"--")}</strong><small>{pick(row,["industry_code"],"")}</small></td><td><ScoreBar value={pick(row,["combined_score","state.score"],0)}/></td><td>{Number(pick(row,["raw_score","state.score"],0)).toFixed(1)}</td><td>{Number(pick(row,["narrative_score"],0)).toFixed(1)}</td><td>{fmtPct(pick(row,["coverage","state.coverage"]),false)}</td><td>{pick(row,["narrative_lifecycle","lifecycle","state.lifecycle"],"证据不足")}</td><td>{fmtPct(pick(row,["target_weight"],0),false)}</td><td><Status>{industryConclusion(row)}</Status></td></tr>)}</tbody></table></div></Section>}
    {view==="themes"&&<Section title="主题与叙事评分" detail="按主题分数、生命周期、可晋升状态和公司映射判断主线强度。"><div className="research-score-grid">{themeRows.map((row,i)=><article key={String(row.theme_code||i)}><header><div><span>#{i+1}</span><h3>{pick(row,["theme_name","name","theme_code"],"未命名主题")}</h3><small>{row.theme_code}</small></div><Status>{row.promotable?"可晋升":pick(row,["lifecycle"],"观察")}</Status></header><ScoreBar value={row.score}/><dl><div><dt>生命周期</dt><dd>{pick(row,["lifecycle"],"--")}</dd></div><div><dt>映射公司</dt><dd>{Array.isArray(row.companies)?row.companies.length:0}</dd></div><div><dt>行业</dt><dd>{pick(row,["payload.knowledge_graph.industry"],"--")}</dd></div><div><dt>时点</dt><dd>{pick(row,["as_of_date"],"--")}</dd></div></dl><EvidenceDetails title="主题公司与评分证据"><pre>{JSON.stringify({payload:row.payload,companies:row.companies},null,2)}</pre></EvidenceDetails></article>)}</div></Section>}
    {view==="pools"&&<Section title="股票池研究评分" detail="观察池、核心候选和持仓池只读展示；评分不足不会因进入列表而自动升级。"><div className="table-wrap"><table><thead><tr><th>排名</th><th>股票</th><th>研究分</th><th>池类型</th><th>状态</th><th>准入理由</th><th>更新时间</th></tr></thead><tbody>{poolRows.map((row,i)=><tr key={String(row.id||i)}><td>{i+1}</td><td><strong>{pick(row,["name","ts_code"],"--")}</strong><small>{row.ts_code}</small></td><td><ScoreBar value={row.research_score}/></td><td>{pick(row,["pool_type"],"--")}</td><td><Status>{researchStatus(row)}</Status></td><td>{pick(row,["reason"],"--")}</td><td>{pick(row,["updated_at","entered_at"],"--")}</td></tr>)}</tbody></table></div></Section>}
    {view==="events"&&<Section title="事件影响与反证" detail="按衰减后影响分排序；负面事件和到期复核必须回到投资逻辑。"><div className="table-wrap"><table><thead><tr><th>股票</th><th>事件</th><th>方向</th><th>影响分</th><th>置信度</th><th>跟踪状态</th><th>下一步</th></tr></thead><tbody>{eventRows.map((row,i)=><tr key={String(row.id||i)}><td>{pick(row,["ts_code"],"--")}</td><td><strong>{pick(row,["title","event_type"],"--")}</strong><small>{pick(row,["event_date"],"")}</small></td><td>{pick(row,["impact_direction"],"--")}</td><td><ScoreBar value={pick(row,["impact.decayed_score","impact.score","score"],0)}/></td><td>{fmtPct(pick(row,["confidence"]),false)}</td><td><Status>{pick(row,["follow_up.status","status"],"未跟踪")}</Status></td><td>{pick(row,["follow_up.next_action","summary"],"--")}</td></tr>)}</tbody></table></div></Section>}
    <ResearchDrilldown pools={pools} industries={industries}/><div className="two-column"><Section title="投资逻辑状态"><CompactTable rows={theses.slice(0,20)} columns={[["股票","ts_code"],["逻辑","title","hypothesis"],["状态","derived_status","status"],["置信度","derived_confidence","confidence"],["复核","review_date","next_review_at"]]}/></Section><Section title="一致预期"><CompactTable rows={rowsFrom(data.analystConsensus,["items","stocks","consensus"]).slice(0,20)} columns={[["股票","ts_code","name"],["状态","status"],["评级","rating","consensus_rating"],["目标价","target_price"]]}/></Section></div><Section title="研究治理与合同"><div className="two-column"><EvidenceDetails title="数据资产与能力缺口"><pre>{JSON.stringify({assets:data.researchDataAssets,governance:data.researchGovernance},null,2)}</pre></EvidenceDetails><EvidenceDetails title="持仓状态与评分合同"><pre>{JSON.stringify({positionState:data.researchPositionState,contracts:data.researchContracts},null,2)}</pre></EvidenceDetails></div></Section></>;
}

function rowsFrom(source: Json|undefined, keys:string[]):Json[]{const direct=firstArray(source,keys);if(direct.length)return direct;if(source&&typeof source==="object")return Object.entries(source).filter(([,v])=>v&&typeof v==="object").map(([key,value])=>({key,...value as Json}));return []}
function objectRows(source: unknown):Json[]{return source&&typeof source==="object"&&!Array.isArray(source)?Object.entries(source as Json).filter(([,value])=>value&&typeof value==="object").map(([key,value])=>({key,...value as Json})):[]}

function apiCatalogRows(source?:Json){const paths=source?.paths&&typeof source.paths==="object"?source.paths:{};const covered=new Set(Object.values(endpoints).map(value=>value.split("?")[0]));return Object.entries(paths).flatMap(([path,methods])=>Object.entries(methods as Json).filter(([method])=>["get","post","put","patch","delete"].includes(method)).map(([method,contract])=>({path,method:method.toUpperCase(),summary:pick(contract as Json,["summary","operationId"],"--"),covered:method==="get"&&covered.has(path)?"前端已读取":method==="get"?"待分类/聚合":"后台控制面"})));}

export function FactorLab({data}:{data:ConsoleData}){
  const rows=rowsFrom(data.factors,["definitions","factors","registry","items"]);
  return <><PageHeader eyebrow="FACTOR PLATFORM" title="因子平台" summary="查看注册版本、生产状态、点时物化和未来评价积累。"/><div className="metric-grid headline-metrics"><Metric label="注册因子" value={rows.length}/><Metric label="生产因子" value={pick(data.factors,["active_count"],rows.filter(x=>String(pick(x,["status","stage"]))==="production").length)}/><Metric label="候选因子" value={pick(data.factors,["candidate_count"],rows.filter(x=>String(pick(x,["status","stage"]))==="candidate").length)}/><Metric label="评价记录" value={pick(data.factors,["evaluation_count"],0)}/></div><Section title="注册表" detail="交易约束因子不会参与 Alpha IC 晋升。"><CompactTable rows={rows} columns={[["因子","name_cn","factor_key","name"],["状态","status","stage"],["版本","version","registry_version"],["分类","category"]]}/></Section><EvidenceDetails title="完整因子合同"><pre>{JSON.stringify({registry:data.factors,status:data.factorStatus},null,2)}</pre></EvidenceDetails></>;
}

export function ModelGovernance({data}:{data:ConsoleData}){
  const planModels=firstArray(data.planModels,["items"]);const registryVersions=rowsFrom(data.models,["versions"]);const reports=rowsFrom(data.modelReports,["items","reports"]);const counts=(data.planModels?.counts||{}) as Json;const hsmm={model_key:"market_regime_hsmm_v1",name:"市场状态 HSMM",role:"识别市场状态、风险预算和防御切换",family:"Gaussian HSMM",status:pick(data.modelGovernance,["status","production.status","active_version.status"],pick(data.modelMarketLive,["status"],"已登记")),active_version:pick(data.modelGovernance,["active_version","production_version"],null),coverage:pick(data.modelGovernance,["coverage","training_coverage"],{}),blocked_reasons:pick(data.modelGovernance,["blocked_reasons","promotion.blocked_reasons"],[])};const families=[hsmm,...planModels];const productionCount=planModels.filter(row=>row.status==="production").length+(String(hsmm.status).includes("production")||pick(hsmm.active_version as Json,["id","version"],null)?1:0);const degradedCount=families.filter(row=>/degrad|artifact_missing|failed/.test(String(pick(row,["health.status","active_artifact.status","status"],"")))).length;
  return <><PageHeader eyebrow="MODEL GOVERNANCE" title="模型治理" summary="按模型族查看生产版本、数据覆盖、训练验证、降级影响和确定性回退。"/><div className="metric-grid headline-metrics"><Metric label="核心模型族" value={families.length} note="5 个计划模型 + 1 个市场状态模型"/><Metric label="生产激活" value={productionCount}/><Metric label="候选 / 可训练" value={Number(counts.candidate||0)+Number(counts.trainable||0)} note={`${counts.candidate||0} 候选 · ${counts.trainable||0} 可训练`}/><Metric label="降级 / 异常" value={degradedCount} tone={degradedCount?"watch":"good"}/></div><Section title="核心模型族" detail="状态来自各模型自己的治理合同，不再把通用 main 训练版本误当作模型总数。"><div className="model-family-grid">{families.map((row,i)=>{const active=pick(row,["active_version"],{}) as Json;const latest=pick(row,["latest_version"],{}) as Json;const coverage=pick(row,["coverage"],{}) as Json;const artifact=pick(row,["active_artifact"],{}) as Json;const blockers=pick(row,["blocked_reasons"],[]) as unknown;return <article key={String(row.model_key||i)}><header><div><span>{pick(row,["family"],"MODEL")}</span><h3>{pick(row,["name","model_key"],"模型")}</h3><small>{row.model_key}</small></div><Status>{pick(row,["status"],"unknown")}</Status></header><p>{pick(row,["role"],"未登记模型职责")}</p><dl><div><dt>生产版本</dt><dd>{pick(active,["version","id"],"未激活")}</dd></div><div><dt>最新版本</dt><dd>{pick(latest,["version","id"],pick(active,["version","id"],"--"))}</dd></div><div><dt>数据覆盖</dt><dd>{pick(coverage,["effective_sessions","eligible_sessions","sessions"],"--")} / {pick(coverage,["minimum_sessions","required_sessions"],"--")}</dd></div><div><dt>产物</dt><dd>{pick(artifact,["status"],active&&Object.keys(active).length?"已绑定":"未激活")}</dd></div></dl><EvidenceDetails title="训练、验证与阻塞证据"><pre>{JSON.stringify({training_contract:(row as Json).training_contract,latest_train_run:(row as Json).latest_train_run,validation:latest.validation,blocked_reasons:Array.isArray(blockers)?blockers:[],fallback:pick(data.modelOutputContracts,[`contracts.${row.model_key}.fallback`],null),required_data:(row as Json).required_data},null,2)}</pre></EvidenceDetails></article>})}</div></Section><div className="two-column"><Section title="市场状态模型" detail="当前状态、历史和晋升治理。"><dl className="fact-list"><div><dt>当前市场状态</dt><dd><Status>{pick(data.modelMarketLive,["market_state","state","status"],"证据缺失")}</Status></dd></div><div><dt>置信度</dt><dd>{fmtPct(pick(data.modelMarketLive,["confidence","probability"]),false)}</dd></div><div><dt>历史记录</dt><dd>{rowsFrom(data.modelMarketHistory,["items","history"]).length}</dd></div></dl><EvidenceDetails title="HSMM 治理合同"><pre>{JSON.stringify({live:data.modelMarketLive,governance:data.modelGovernance},null,2)}</pre></EvidenceDetails></Section><Section title="生产策略与总控" detail="模型如何进入排序、动作与风险预算。"><EvidenceDetails title="生产绑定、Controller 与验证"><pre>{JSON.stringify({production:data.modelProduction,controller:data.modelController,validation:data.modelValidation},null,2)}</pre></EvidenceDetails></Section></div><Section title="证据字段与回退" detail="每个决策字段由哪些模型提供，模型不可用时使用什么确定性规则。"><CompactTable rows={objectRows(pick(data.modelEvidenceBindings,["bindings"],{}))} columns={[["决策字段","key"],["主模型","primary"],["确定性回退","fallback"]]}/></Section><div className="two-column"><Section title="绩效与训练工作台"><CompactTable rows={reports.slice(0,20)} columns={[["模型","model_key","name"],["版本","version","version_id"],["状态","status"],["指标","metric","score","net_lift"],["时间","created_at","generated_at"]]}/><EvidenceDetails title="完整训练工作台"><pre>{JSON.stringify(data.modelWorkbench||{},null,2)}</pre></EvidenceDetails></Section><Section title="底层通用模型注册" detail="这些是 main 训练版本记录，不代表模型族数量。"><CompactTable rows={registryVersions} columns={[["注册键","model_key"],["版本","version","id"],["状态","status"],["训练时间","trained_at","created_at"]]}/></Section></div></>;
}

export function DataAssets({data}:{data:ConsoleData}){
  const assets=rowsFrom(data.watermarks,["items","assets","datasets"]);const failed=rowsFrom(data.failedRequests,["items","requests","failed_requests"]);const logs=rowsFrom(data.runtimeLogs,["items","logs"]);
  return <><PageHeader eyebrow="DATA PLATFORM" title="数据资产" summary="查看决策硬门、资产水位、失败分类和确定性运维结果。"/><div className="metric-grid headline-metrics"><Metric label="资产" value={assets.length}/><Metric label="失败请求" value={failed.length} tone={failed.length?"watch":"good"}/><Metric label="OOS 硬数据" value={`${pick(data.oos,["eligible_sessions"],"--")}/${pick(data.oos,["required_sessions"],1537)}`}/><Metric label="密封集" value={`${pick(data.sealed,["eligible_sessions"],"--")}/${pick(data.sealed,["required_sessions"],126)}`}/></div><Section title="资产与水位" detail="数据存在不等于字段、点时和覆盖合同完整。"><CompactTable rows={assets} columns={[["资产","name","dataset","asset_key","key"],["状态","status","readiness"],["覆盖","coverage","row_count","eligible_sessions"],["水位","watermark","latest_trade_date","updated_at"]]}/></Section><div className="two-column"><Section title="日更与数据流"><EvidenceDetails title="日更、流与可观测性"><pre>{JSON.stringify({daily:data.dailyUpdateStatus,streams:data.dataStreams,observability:data.dataObservability},null,2)}</pre></EvidenceDetails></Section><Section title="补全计划与进度"><EvidenceDetails title="只读补全合同"><pre>{JSON.stringify({plan:data.backfillPlan,status:data.backfillStatus},null,2)}</pre></EvidenceDetails></Section></div><div className="two-column"><Section title="失败请求分类"><CompactTable rows={failed.slice(0,20)} columns={[["接口","api_name","source","key"],["类别","category","status"],["尝试","attempts","attempt_count"],["错误","error","message"]]}/></Section><Section title="LLM 数据运维"><EvidenceDetails title="治理与执行证据"><pre>{JSON.stringify(data.dataOperations||{},null,2)}</pre></EvidenceDetails></Section></div><Section title="运行日志" detail="最近 100 条数据平台结构化日志。"><CompactTable rows={logs.slice(0,30)} columns={[["时间","created_at","timestamp"],["级别","level"],["模块","logger","module"],["消息","message","summary"]]}/></Section></>;
}

export function EvidenceChain({data}:{data:ConsoleData}){
  const decisions=rowsFrom(data.decisions,["items","decisions"]);const reviews=rowsFrom(data.reviews,["items","reviews"]);const ledger=firstArray(data.ledgerDetail,["items"]);const reports=rowsFrom(data.performanceReports,["items","reports"]);const proposals=rowsFrom(data.llmProposals,["items"]);const backtests=rowsFrom(data.backtests,["items"]);const [selectedId,setSelectedId]=useState<number>(Number(decisions[0]?.id||0));const [verification,setVerification]=useState<Json>({});const selected=decisions.find(row=>Number(row.id)===selectedId)||decisions[0]||{};const execution=ledger.find(row=>Number(pick(row,["execution_id","id"],0))===Number(selected.execution_id||0));const review=reviews.find(row=>Number(row.decision_snapshot_id||0)===Number(selected.id||0));
  useEffect(()=>{const id=Number(selected.id||0);if(!id){setVerification({});return}const controller=new AbortController();readApi(`/api/research/evidence/verify/${id}`,controller.signal).then(setVerification).catch(error=>setVerification({ok:false,status:"verification_unavailable",reason:String(error)}));return()=>controller.abort()},[selected.id]);
  const marketState=pick(selected,["market_state.label","market_state.state","market_state"],"--");const researchScore=pick(selected,["research_state.score","research_state.research_score"],"--");const valuationStatus=pick(selected,["valuation.status","valuation.method"],"--");const contract=pick(selected,["target_weight_contract"],{}) as Json;const outcome=pick(review,["outcome"],{}) as Json;const attribution=pick(review,["attribution"],{}) as Json;
  return <><PageHeader eyebrow="AUDIT EVIDENCE" title="决策证据链" summary="选择一次冻结决策，追踪当时数据、版本、动作、成交、收益和复盘。"/><div className="metric-grid headline-metrics"><Metric label="冻结决策" value={decisions.length}/><Metric label="已关联执行" value={decisions.filter(row=>row.execution_id).length}/><Metric label="已完成复盘" value={new Set(reviews.map(row=>row.decision_snapshot_id)).size}/><Metric label="证据异常" value={pick(data.decisionAudit,["quality.future_data_violations"],0)+pick(data.decisionAudit,["quality.missing_evidence"],0)} tone={pick(data.decisionAudit,["quality.future_data_violations"],0)+pick(data.decisionAudit,["quality.missing_evidence"],0)>0?"danger":"good"}/></div><Section title="选择决策"><label className="detail-select"><span>冻结决策快照</span><select value={Number(selected.id||0)} onChange={event=>setSelectedId(Number(event.target.value))}>{decisions.map(row=><option key={row.id} value={row.id}>#{row.id} · {pick(row,["decision_time"],"--")} · {pick(row,["ts_code"],"组合")} · {pick(row,["decision_type"],"--")}</option>)}</select></label></Section>{decisions.length?<><Section title={`决策 #${selected.id} · ${pick(selected,["ts_code"],"组合")}`} detail={String(pick(selected,["reason"],"未记录决策原因"))}><div className="audit-summary"><div><span>动作</span><strong>{pick(selected,["decision_type"],"--")}</strong></div><div><span>决策时间</span><strong>{pick(selected,["decision_time"],"--")}</strong></div><div><span>数据截止</span><strong>{pick(selected,["data_as_of_time"],"--")}</strong></div><div><span>证据完整性</span><Status tone={verification.verified?"good":"danger"}>{pick(verification,["status"],"校验中")}</Status></div></div></Section><div className="audit-timeline"><article><div className="audit-step">1</div><section><header><span>DATA</span><h2>点时数据冻结</h2><Status tone={String(selected.data_as_of_time)<=String(selected.decision_time)?"good":"danger"}>{String(selected.data_as_of_time)<=String(selected.decision_time)?"无未来数据":"时间违规"}</Status></header><dl><div><dt>数据截止</dt><dd>{pick(selected,["data_as_of_time"],"--")}</dd></div><div><dt>市场状态</dt><dd>{scalarLabel(marketState)}</dd></div><div><dt>研究评分</dt><dd>{String(researchScore)}</dd></div><div><dt>估值状态</dt><dd>{scalarLabel(valuationStatus)}</dd></div></dl><EvidenceDetails title="冻结市场、研究与估值证据"><pre>{JSON.stringify({market_state:selected.market_state,research_state:selected.research_state,valuation:selected.valuation},null,2)}</pre></EvidenceDetails></section></article><article><div className="audit-step">2</div><section><header><span>VERSION</span><h2>模型与策略版本</h2><Status>{pick(selected,["evidence_schema_version"],"未登记")}</Status></header><dl><div><dt>模型版本</dt><dd>{pick(selected,["model_version"],"--")}</dd></div><div><dt>证据哈希</dt><dd className="hash-value">{pick(selected,["evidence_hash"],"--")}</dd></div><div><dt>权重动作</dt><dd>{pick(contract,["action","function_bucket"],"--")}</dd></div><div><dt>目标权重</dt><dd>{fmtPct(pick(contract,["target_weight"]),false)}</dd></div></dl><EvidenceDetails title="组合与目标权重合同"><pre>{JSON.stringify({portfolio_context:selected.portfolio_context,target_weight_contract:contract,verification},null,2)}</pre></EvidenceDetails></section></article><article><div className="audit-step">3</div><section><header><span>EXECUTION</span><h2>计划与模拟成交</h2><Status tone={selected.execution_id?"good":"watch"}>{selected.execution_id?"已关联执行":"无关联成交"}</Status></header><dl><div><dt>执行批次</dt><dd>{pick(selected,["execution_id"],"--")}</dd></div><div><dt>逐笔操作</dt><dd>{pick(selected,["operation_id"],"--")}</dd></div><div><dt>成交日</dt><dd>{pick(execution,["execute_date","executed_at"],"--")}</dd></div><div><dt>费用</dt><dd>{fmtMoney(pick(execution,["summary.total_fee","total_fee","fees"]))}</dd></div></dl><EvidenceDetails title="成交批次与账本证据"><pre>{JSON.stringify(execution||{status:"未关联执行批次"},null,2)}</pre></EvidenceDetails></section></article><article><div className="audit-step">4</div><section><header><span>OUTCOME</span><h2>后续结果与复盘</h2><Status tone={review?"good":"watch"}>{review?"已复盘":"等待未来结果"}</Status></header><dl><div><dt>复盘时间</dt><dd>{pick(review,["review_time","created_at"],"--")}</dd></div><div><dt>错误类型</dt><dd>{pick(review,["error_type"],"无")}</dd></div><div><dt>后续收益</dt><dd>{fmtPct(pick(outcome,["return","stock_return","directional_return"]))}</dd></div><div><dt>经验结论</dt><dd>{pick(review,["lessons"],"等待成熟样本")}</dd></div></dl><EvidenceDetails title="结果与归因"><pre>{JSON.stringify({outcome,attribution},null,2)}</pre></EvidenceDetails></section></article></div></>:<Empty title="尚无冻结决策" detail="正式决策产生后将在这里形成审计时间线。"/>}<div className="two-column"><Section title="周期绩效与回测"><CompactTable rows={[...reports,...backtests].slice(0,30)} columns={[["类型","period_type","report_type","name"],["状态","status"],["收益","return_pct","total_return","period_return"],["时间","created_at","generated_at"]]}/></Section><Section title="LLM 提案治理"><dl className="fact-list"><div><dt>预算状态</dt><dd><Status>{pick(data.llmBudget,["status"],"证据缺失")}</Status></dd></div><div><dt>已用 Token</dt><dd>{pick(data.llmBudget,["used_tokens","usage.total_tokens"],"--")}</dd></div><div><dt>提案数量</dt><dd>{proposals.length}</dd></div><div><dt>生产修改</dt><dd>禁止</dd></div></dl><CompactTable rows={proposals.slice(0,12)} columns={[["提案","title","hypothesis","proposal_type"],["类型","target_type","kind"],["状态","status","governance_status"],["时间","created_at"]]}/></Section></div><Section title="独立账本与学习治理"><div className="two-column"><EvidenceDetails title="现金、持仓和漂移审计"><pre>{JSON.stringify(data.ledgerAudit||{},null,2)}</pre></EvidenceDetails><EvidenceDetails title="周期学习合同"><pre>{JSON.stringify({learning:data.reviewLearning,daily:data.report},null,2)}</pre></EvidenceDetails></div></Section></>;
}

function CompactTable({rows,columns}:{rows:Json[],columns:string[][]}){return rows.length?<div className="table-wrap"><table><thead><tr>{columns.map(c=><th key={c[0]}>{c[0]}</th>)}</tr></thead><tbody>{rows.map((row,i)=><tr key={i}>{columns.map(c=>{const value=pick(row,c.slice(1),"--");return <td key={c[0]}>{typeof value==="object"?JSON.stringify(value):String(value)}</td>})}</tr>)}</tbody></table></div>:<Empty/>}

export function Operations({ data }: { data: ConsoleData }) {
  const owner=unwrapOwner(data.owner); const tasks=firstArray(data.tasks,["tasks","items"]); const logs=firstArray(data.tasks,["logs"]); const incidents=ownerIncidents(owner);const apiRows=apiCatalogRows(data.apiCatalog);const readApis=apiRows.filter(row=>row.method==="GET");const coveredApis=readApis.filter(row=>row.covered==="前端已读取");const quantTasks=rowsFrom(data.quantTasks,["items","tasks"]);const executions=rowsFrom(data.executions,["items"]);const operations=rowsFrom(data.operations,["items"]);
  const grouped=[{key:"self_healing",title:"系统正在自行处理",tone:"info"},{key:"waiting_condition",title:"等待自然条件或上游发布",tone:"watch"},{key:"internal_fault",title:"内部故障",tone:"danger"},{key:"owner_required",title:"需要所有者授权",tone:"danger"}] as const;
  return <><a className="back-link" href="/overview">← 返回总览</a><PageHeader eyebrow="SYSTEM OPERATIONS" title="系统运行" summary="技术维护区默认收敛；任务、数据、模型和异常证据按责任查看。" />
    <div className="metric-grid headline-metrics"><Metric label="自治任务" value={tasks.length} note="最近任务与模块"/><Metric label="量化任务" value={quantTasks.length}/><Metric label="只读接口覆盖" value={`${coveredApis.length}/${readApis.length}`} note="直接读取；其余待聚合或分类"/><Metric label="后台控制接口" value={apiRows.filter(row=>row.method!=="GET").length} note="不提供人工按钮"/></div>
    <Section title="自治任务" detail="步骤、租约、重试与恢复证据。">{tasks.length?<div className="task-list">{tasks.slice(0,16).map((row,i)=>{const raw=Number(pick(row,["progress","progress_pct"],0));const pct=raw<=1?raw*100:raw;return <div key={i}><Status>{pick(row,["status","state"],"未知")}</Status><div><strong>{pick(row,["name","task_name","module"],"自治任务")}</strong><p>{pick(row,["current_step","message","summary"],"暂无步骤摘要")}</p><EvidenceDetails title="检查点、租约与重试"><pre>{JSON.stringify({phase:row.phase,checkpoint:row.checkpoint,attempt:row.attempt,max_attempts:row.max_attempts,heartbeat_at:row.heartbeat_at,next_step:row.next_step,next_run_at:row.next_run_at,error:row.error},null,2)}</pre></EvidenceDetails></div><div><b>{Math.round(pct)}%</b><small>{pick(row,["updated_at","heartbeat_at"],"--")}</small></div></div>})}</div>:<Empty title="暂无任务证据" detail="任务中心接口未返回最近任务。" />}</Section>
    <Section title="异常责任分组" detail="未来样本不足、冷却期和窗口未前移不显示为红色故障。"><div className="responsibility-grid">{grouped.map(group=>{const rows=incidents.filter(x=>{const kind=String(pick(x,["resolution_class","disposition","category","kind"],"waiting_condition"));return group.key==="self_healing"?kind==="self_managed":kind===group.key});return <div key={group.key}><header><Status tone={group.tone}>{rows.length}</Status><strong>{group.title}</strong></header>{rows.length?rows.map((row,i)=><article key={i}><b>{pick(row,["title","summary","module","name"],"运行事项")}</b><p>{pick(row,["reason","detail","message","next_review"],"等待复核")}</p></article>):<small>当前没有此类事项</small>}</div>})}</div></Section>
    <Section title="结构化日志" detail="最近任务中心日志，不把历史失败误报为当前故障。"><CompactTable rows={logs.slice(0,40)} columns={[["时间","created_at","timestamp"],["级别","level"],["模块","logger","module"],["消息","message"]]}/></Section>
    <div className="two-column"><Section title="量化任务与最近运行"><CompactTable rows={quantTasks.slice(0,20)} columns={[["任务","id","task_id","name"],["类型","task_type","kind"],["状态","status","state"],["进度","progress","progress_pct"],["更新时间","updated_at","finished_at"]]}/><CompactTable rows={rowsFrom(data.quantRecent,["items"]).slice(0,10)} columns={[["信号日","signal_date"],["执行日","execute_date"],["卖出","sold_count"],["买入","bought_count"],["摘要","message"]]}/><EvidenceDetails title="运行状态与调度"><pre>{JSON.stringify({status:data.quantStatus,schedule:data.evolutionSchedule,evolutionTasks:data.evolutionTasks},null,2)}</pre></EvidenceDetails></Section><Section title="执行批次与逐笔操作"><CompactTable rows={executions.slice(0,20)} columns={[["执行","id"],["策略","strategy_id"],["执行时间","executed_at"],["预算","budget"],["订单","orders"]]}/><CompactTable rows={operations.slice(0,20)} columns={[["执行","execution_id"],["股票","symbol"],["动作","side"],["数量","quantity"],["佣金","commission"],["价格","price"]]}/></Section></div>
    <Section title="后端接口地图" detail="实时读取 OpenAPI；GET 接口逐步映射为页面或聚合证据，写接口仅标记后台所有权。"><div className="metric-grid"><Metric label="全部接口" value={apiRows.length}/><Metric label="GET" value={readApis.length}/><Metric label="前端直接读取" value={coveredApis.length}/><Metric label="后台写接口" value={apiRows.filter(row=>row.method!=="GET").length}/></div><CompactTable rows={apiRows} columns={[["方法","method"],["路径","path"],["用途","summary"],["前端处置","covered"]]}/></Section>
    <EvidenceDetails title="查看原始运行合同"><pre>{JSON.stringify({tasks:data.tasks,oos:data.oos,sealed:data.sealed},null,2)}</pre></EvidenceDetails>
  </>;
}
